    void groupsHunksFromDiffRows() {
        List<DiffReviewPanel.DiffRow> rows = DiffEngine.lines("a\nb\nc", "a\nB\nc\nd");
        List<DiffEngine.DiffHunk> hunks = DiffEngine.hunks(rows);
        assertFalse(hunks.isEmpty());
    }
}

