        String id = str(payload.get("approval_id"), "");
        Alert alert = new Alert(Alert.AlertType.CONFIRMATION);
        alert.setTitle("Approval · Window #" + windowId);
        alert.setHeaderText(str(payload.get("tool"), "tool") + "  ·  risk: " + str(payload.get("risk"), "?"));
