private int lineNumberAt(int offset) {
        String text = code.getText();
        if (text == null || text.isEmpty() || offset <= 0) {
            return 0;
        }
        int line = 0;
        int limit = Math.min(offset, text.length());
        for (int i = 0; i < limit; i++) {
            if (text.charAt(i) == '\n') {
                line++;
            }
        }
        return line;
    }

