class RunAnchorsTest {

    @Test
    void anchorsSurviveCompactionSummary() {
        RunAnchors anchors = new RunAnchors();
        anchors.recordRead("src/A.java");
        anchors.recordWrite("src/B.java");
        anchors.recordFailure("error: cannot find symbol");

        List<Map<String, Object>> messages = new ArrayList<>();
        messages.add(Map.of("role", "developer", "content", "system"));
        for (int i = 0; i < 30; i++) {
            Map<String, Object> assistant = new LinkedHashMap<>();
            assistant.put("role", "assistant");
            assistant.put("content", "");
            assistant.put(
                    "tool_calls",
                    List.of(Map.of(
                            "id", "call_" + i,
                            "type", "function",
                            "function", Map.of("name", "fs.read", "arguments", "{}"))));
            messages.add(assistant);
            messages.add(Map.of("role", "tool", "tool_call_id", "call_" + i, "name", "fs.read", "content", "x".repeat(6000)));
        }

        ContextCompactor.Result result = ContextCompactor.compact(messages, new ContextBudget(1000, 500, 8, 2000), anchors);
        assertTrue(result.compacted());
        String anchor = result.messages().stream()
                .filter(m -> "developer".equals(m.get("role")))
                .map(m -> String.valueOf(m.get("content")))
                .filter(c -> c.contains("[compaction]"))
                .findFirst()
                .orElse("");
        assertTrue(anchor.contains("read_files"));
        assertTrue(anchor.contains("src/A.java"));
        assertTrue(anchor.contains("modified_files"));
        assertTrue(anchor.contains("last_failure"));
    }
}

