        }
        if (!files.isEmpty()) {
            sb.append("\nfiles_seen:\n");
            for (String f : files) {
                sb.append("- ").append(f).append('\n');
            }
        }
        sb.append("</explore_report>");
        return sb.toString().trim();
    }

