private static Map<String, Object> toolResult(ToolCallIntent call, String status, String content) {
        Map<String, Object> item = new LinkedHashMap<>();
        item.put("role", "tool");
        item.put("tool_call_id", call.id());
        item.put("name", call.name());
        item.put("status", status);
        item.put("content", content);
        return item;
    }

private static void appendAssistantTools(List<Map<String, Object>> history, List<ToolCallIntent> calls) {
        List<Map<String, Object>> toolCalls = new ArrayList<>();
        for (ToolCallIntent call : calls) {
            Map<String, Object> fn = Map.of("name", call.name(), "arguments", call.arguments() == null ? Map.of() : call.arguments());
            toolCalls.add(Map.of("id", call.id(), "type", "function", "function", fn));
        }
        history.add(Map.of("role", "assistant", "content", "", "tool_calls", toolCalls));
    }

public final class PlanParser {

    private static final Pattern CHECKBOX = Pattern.compile("^\\s*[-*]\\s*\\[[ xX]?\\]\\s+(.+)$");
    private static final Pattern NUMBERED = Pattern.compile("^\\s*\\d+[.)]\\s+(.+)$");

    private PlanParser() {}

    public static List<String> steps(String planMarkdown) {
        if (planMarkdown == null || planMarkdown.isBlank()) {
            return List.of();
        }
        List<String> steps = new ArrayList<>();
        for (String line : planMarkdown.split("\n")) {
            String trimmed = line.trim();
            if (trimmed.isEmpty()) {
                continue;
            }
            Matcher cb = CHECKBOX.matcher(line);
            if (cb.find()) {
                steps.add(cb.group(1).trim());
                continue;
            }
            Matcher num = NUMBERED.matcher(line);
            if (num.find()) {
                steps.add(num.group(1).trim());
            }
        }
        return List.copyOf(steps);
    }

    public static String formatStepsBlock(List<String> steps) {
        if (steps.isEmpty()) {
            return "";
        }
        StringBuilder sb = new StringBuilder("<plan_steps path=\"" + PlanTool.PLAN_PATH + "\">\n");
        int i = 1;
        for (String step : steps) {
            sb.append(i++).append(". ").append(step).append('\n');
        }
        sb.append("</plan_steps>");
        return sb.toString();
    }
}

