    private static int findBlock(List<String> lines, List<String> block, int hint) {
        if (block.isEmpty()) {
            return hint;
        }

private static int findBlock(List<String> lines, List<String> block, int hint) {
        if (block.isEmpty()) {
            return hint;
        }
        for (int start = Math.max(0, hint - 3); start <= Math.min(lines.size() - block.size(), hint + 3); start++) {
            if (matchesBlock(lines, start, block)) {
                return start;
            }
        }
        for (int start = 0; start <= lines.size() - block.size(); start++) {
            if (matchesBlock(lines, start, block)) {
                return start;
            }
        }
        return -1;
    }

private static int findBlockFuzzy(List<String> lines, List<String> block, int hint) {
        if (block.isEmpty()) {
            return hint;
        }
        String blockText = String.join("\n", block);
        String fileText = String.join("\n", lines);
        FuzzyMatcher.Match norm = FuzzyMatcher.normalized(fileText, blockText);
        if (norm == null) {
            return -1;
        }
        String matched = norm.text();
        List<String> matchedLines = List.of(matched.split("\n", -1));
        return findBlock(lines, matchedLines, hint);
    }

return findBlock(lines, matchedLines, hint);
    }

    private static boolean matchesBlock(List<String> lines, int start, List<String> block) {
        for (int i = 0; i < block.size(); i++) {
            if (!lines.get(start + i).equals(block.get(i))) {
                return false;
            }
        }

private static boolean matchesBlock(List<String> lines, int start, List<String> block) {
        for (int i = 0; i < block.size(); i++) {
            if (!lines.get(start + i).equals(block.get(i))) {
                return false;
            }
        }
        return true;
    }

private static int countOccurrences(String haystack, String needle) {
        int count = 0;
        int idx = 0;
        while ((idx = haystack.indexOf(needle, idx)) >= 0) {
            count++;
            idx += needle.length();
        }
        return count;
    }

