private void syncDocument(String relativePath) throws IOException {
        Path abs = workspaceRoot.resolve(relativePath).normalize();
        if (!Files.isRegularFile(abs)) {
            return;
        }
        String uri = toUri(relativePath);
        String text = Files.readString(abs);
        docVersion++;
        ObjectNode params = JSON.createObjectNode();
        params.set("textDocument", LspJsonRpc.textDocumentItem(uri, "java", docVersion, text));
        rpc.notify("textDocument/didOpen", params);
    }

private Process tryStartJdtls() {
        String home = System.getenv("JDTLS_HOME");
        if (home == null || home.isBlank()) {
            return null;
        }
        try {
            Path launcherDir = Path.of(home, "plugins");
            if (!Files.isDirectory(launcherDir)) {
                return null;
            }
            Path launcher = Files.list(launcherDir)
                    .filter(p -> p.getFileName().toString().startsWith("org.eclipse.equinox.launcher_"))
                    .findFirst()
                    .orElse(null);
            if (launcher == null) {
                return null;
            }
            Path config = Path.of(home, "config_mac");
            if (!Files.isDirectory(config)) {
                config = Path.of(home, "config_linux");
            }
            if (!Files.isDirectory(config)) {
                config = Path.of(home, "config_win");
            }
            Path dataDir = Files.createTempDirectory("anvil-jdtls-");
            ProcessBuilder pb = new ProcessBuilder(
                    "java",
                    "-Declipse.application=org.eclipse.jdt.ls.core.id1",
                    "-Dosgi.bundles.defaultStartLevel=4",
                    "-Declipse.product=org.eclipse.jdt.ls.core.product",
                    "-noverify",
                    "-Xmx512M",
                    "-jar",
                    launcher.toString(),
                    "-configuration",
                    config.toString(),
                    "-data",
                    dataDir.toString());
            pb.redirectErrorStream(true);
            return pb.start();
        } catch (Exception e) {
            return null;
        }
    }

private String toUri(String relativePath) {
        Path abs = "."
                .equals(relativePath)
                ? workspaceRoot
                : workspaceRoot.resolve(relativePath).normalize();
        return abs.toUri().toString();
    }

public void close() {
        if (rpc != null) {
            rpc.close();
            rpc = null;
        }
        initialized = false;
        INSTANCES.remove(workspaceRoot);
    }

public final class DiagnosticParser {

    public record Diagnostic(String file, int line, int column, String severity, String message) {}

    private static final Pattern MAVEN =
            Pattern.compile("\\[(ERROR|WARNING)]\\s+([^:\\[]+):\\[(\\d+),(\\d+)]\\s*(.*)");
    private static final Pattern JAVAC = Pattern.compile("^([^:]+):(\\d+):\\s*(?:error:|warning:)?\\s*(.*)$", Pattern.MULTILINE);
    private static final Pattern SIMPLE = Pattern.compile("([^\\s]+\\.java):(\\d+).*?(error|ERROR|cannot find symbol|';' expected)", Pattern.CASE_INSENSITIVE);

    private DiagnosticParser() {}

    public static List<Diagnostic> parse(String output) {
        if (output == null || output.isBlank()) {
            return List.of();
        }
        List<Diagnostic> found = new ArrayList<>();
        Map<String, Diagnostic> dedupe = new LinkedHashMap<>();
        for (String line : output.split("\n")) {
            Diagnostic d = parseLine(line.trim());
            if (d != null) {
                dedupe.putIfAbsent(key(d), d);
            }
        }
        found.addAll(dedupe.values());
        if (found.isEmpty()) {
            Matcher m = SIMPLE.matcher(output);
            while (m.find()) {
                Diagnostic d = new Diagnostic(m.group(1), Integer.parseInt(m.group(2)), 0, "ERROR", m.group(0));
                dedupe.putIfAbsent(key(d), d);
            }
            found.addAll(dedupe.values());
        }
        return List.copyOf(found);
    }

    public static String format(List<Diagnostic> diagnostics, int maxItems) {
        if (diagnostics.isEmpty()) {
            return "no diagnostics parsed";
        }
        StringBuilder sb = new StringBuilder();
        int n = 0;
        for (Diagnostic d : diagnostics) {
            if (n >= maxItems) {
                sb.append("... and ").append(diagnostics.size() - maxItems).append(" more\n");
                break;
            }
            sb.append(d.severity())
                    .append(' ')
                    .append(d.file())
                    .append(':')
                    .append(d.line());
            if (d.column() > 0) {
                sb.append(':').append(d.column());
            }
            sb.append(' ').append(d.message()).append('\n');
            n++;
        }
        return sb.toString().trim();
    }

    private static Diagnostic parseLine(String line) {
        Matcher maven = MAVEN.matcher(line);
        if (maven.find()) {
            return new Diagnostic(
                    maven.group(2).trim(),
                    Integer.parseInt(maven.group(3)),
                    Integer.parseInt(maven.group(4)),
                    maven.group(1),
                    maven.group(5).trim());
        }
        Matcher javac = JAVAC.matcher(line);
        if (javac.find()) {
            return new Diagnostic(
                    javac.group(1).trim(),
                    Integer.parseInt(javac.group(2)),
                    0,
                    line.toLowerCase().contains("warning") ? "WARNING" : "ERROR",
                    javac.group(3).trim());
        }
        return null;
    }

    private static String key(Diagnostic d) {
        return d.file() + ":" + d.line() + ":" + d.column() + ":" + d.message();
    }
}

