                    ? List.of()
                    : stored.chunks.stream()
                            .map(c -> new WorkspaceIndex.CodeChunk(
                                    c.path, c.startLine, c.endLine, c.symbolName, c.kind, c.text))
                            .toList();
            return new WorkspaceIndex(
