        TerminalSession s = sessions.get(sessionId);
        if (s == null) {
            return List.of();
        }
        List<TerminalEvent> result = new ArrayList<>();
        for (TerminalEvent e : s.eventLog) {
            if (e.seq() > fromSeq) {
                result.add(e);
            }
        }
        return result;
