        ThreadRecord thread = threadOr404(thread_id);
        if (thread == null) {
            return ResponseEntity.notFound().build();
        }
        List<Map<String, Object>> refs = LspService.references(thread.workspaceRoot(), path, line, column).stream()
                .map(LspController::toMap)
                .toList();
