     * 清除指定线程的持久化历史记录。
     *
     * @param threadId 线程标识
     */
    void clear(String threadId) {
        if (threadId == null || threadId.isBlank()) {
            return;
        }
        try (PreparedStatement ps = connection.prepareStatement("DELETE FROM thread_history WHERE thread_id = ?")) {
            ps.setString(1, threadId);
            ps.executeUpdate();
